head.script:
scwin.onpageload = function () {

};

/**
 * @method  $p
 * @name    isPopup
 * @cdate   2014-03-11
 * @version 5.0 
 * @author  전병진
 * @description
 *  현재 Window(화면)가 popup인지의 여부를 반환합니다.
 * @param   <Boolean:N> closest   중첩된 wframe 팝업 또는 browser 팝업안에 wframe이 있을 경우, 부모 frame의 팝업 여부 체크.
 * @see 
 * @return  <boolean> 팝업인 경우 true, 팝업이 아닌 경우 false 
 * @exception   
 * @sample
 * |var ispopup = $p.isPopup();
 * |//return 예시 ) false
 * |중첩된 wframe 팝업 또는 browser 팝업안에 wframe이 있을 경우, 팝업 여부를 자식 wframe에서 확인할 경우
 * |var ispopup = $p.isPopup(true);
 * @hidden false
 * @deprecated
 */
scwin.sample_org = function () {

};

scwin.sample = function () {

};

scwin.btn_exam1_onclick = function (e) {
    alert($p.isPopup());
};

scwin.btn_exam2_onclick = function (e) {
    alert($p.isPopup(true));
};

scwin.btn_exam4_1_onclick = function (e) {
    var options = {
        type: "iframePopup",
        id: "popup_exam1",
        width: "500px",
        height: "400px",
        top: 100,
        left: 50,
        popupName: "popup_exam1",
        dataObject: {
            type: "json",
            data: {
                "type": "iframePopup"
            },
            name: "exam_param"
        }
    };

    $p.openPopup("iframePopup_isPopup_WESE-447_(WSQ-5371)_popup1.xml", options);
};

scwin.btn_exam4_2_onclick = function (e) {
    var options = {
        type: "wframePopup",
        id: "popup_exam2",
        width: "500px",
        height: "400px",
        top: 150,
        left: 100,
        popupName: "popup_exam2",
        dataObject: {
            type: "json",
            data: {
                "type": "wframePopup"
            },
            name: "exam_param"
        }
    };

    $p.openPopup("iframePopup_isPopup_WESE-447_(WSQ-5371)_popup1.xml", options);
};

scwin.btn_exam4_3_onclick = function (e) {
    var options = {
        type: "browserPopup",
        id: "popup_exam3",
        width: "500px",
        height: "400px",
        top: 200,
        left: 150,
        popupName: "popup_exam3",
        dataObject: {
            type: "json",
            data: {
                "type": "browserPopup"
            },
            name: "exam_param"
        }
    };

    $p.openPopup("iframePopup_isPopup_WESE-447_(WSQ-5371)_popup1.xml", options);
};

scwin.btn_close_onclick = function (e) {
    var popList = $p.getAllPopupList();
    for (var i = popList.length - 1; i >= 0; i--) {
        $p.closePopup(popList[i].id);  // 열려있는 모든 popup을 닫는다. 닫을 때마다 popList가 제거되므로 array를 역순으로 돌아야 한다.
    }
};
